() => {
  // Monday Mobility classes at 07:30 UTC (5:30pm AEST) from the schedule data
  // Aug 24 already booked. Remaining Mondays through Sep:
  const mondayMobilityIds = [
    // Aug 31 - Mon 5:30pm
    'd042bdde-581d-56bf-91e1-7f803af4d78f',
    // Sep 7 - Mon 5:30pm  
    'da07eb68-a9c6-5e86-a450-75c2cb870f67',
    // Sep 14 - Mon 5:30pm
    'e8f515cf-4bbf-5ce6-9cb5-9908fcad5402',
    // Sep 21 - Mon 5:30pm
    '98423d3b-8eb7-5fbb-8cec-0ba2e8debcb3',
    // Sep 28 - Mon 5:30pm
    'b5513980-2e87-55d4-b499-f44754555350',
  ];

  const results = [];
  const bookOne = (id) => fetch('/graphql', {
    method: 'POST',
    headers: {'content-type': 'application/json'},
    credentials: 'include',
    body: JSON.stringify({
      operationName: 'CreateReservation',
      variables: { classInstanceId: id },
      query: 'mutation CreateReservation($classInstanceId: ID!) { createReservation(classInstanceId: $classInstanceId) { reservation { id status waitlistPosition __typename } errorCode __typename } }'
    })
  }).then(r => r.json()).then(d => ({ id, result: d }));

  return Promise.all(mondayMobilityIds.map(bookOne))
    .then(r => JSON.stringify(r, null, 2));
}

